EXTRA_PROFILES=ROOT/'scripts/physical_profile_extensions.json'
if EXTRA_PROFILES.is_file():
    for item in json.loads(EXTRA_PROFILES.read_text(encoding='utf-8')):
        add(item['id'],item['scope'],item['criteria'],item['selectors'])

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--reuse-receipt',type=Path,help='Reuse passed profiles only after source, tests, environment and artifact checksum verification.')
    parser.add_argument('--workers',type=int,default=4)
    args=parser.parse_args()
    if not 1<=args.workers<=8:parser.error('workers must be between one and eight')
    catalog=ROOT/'src/pipeline_integrity/catalog_data/engineering_methods.json'
    expected={x['id'] for x in json.loads(catalog.read_text(encoding='utf-8'))['methods']}
    assert len(expected)==223 and set(PROFILES)<=expected
    folder=ROOT/'artifacts/physical-campaign-223'/datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ');folder.mkdir(parents=True)
    material=Path(os.environ.get('PIPELINE_FORMULA_MATERIAL_SRC',str(ROOT.parent.parent/'재료_부식 평가 툴 프로젝트/matintegrity/src'))).resolve()
    lh2=Path(os.environ.get('PIPELINE_FORMULA_LH2DT_SRC',str(ROOT.parent/'tmp/analysis/repos/lh2dt_models/src'))).resolve()
    def snapshot():
        paths={Path(__file__),catalog,EXTRA_PROFILES}
        for base in (ROOT/'src',ROOT/'tests',ROOT/'examples',material,lh2):
            for suffix in ('*.py','*.json'):paths.update(base.rglob(suffix))
        return {str(p.resolve()):sha(p) for p in sorted(paths)}
    before=snapshot();(folder/'source-before.json').write_text(json.dumps(before,ensure_ascii=False,indent=2),encoding='utf-8')
    env=os.environ.copy();env.update(PYTHONPATH=os.pathsep.join(map(str,(ROOT/'src',ROOT,ROOT/'tests',material,lh2))),PYTEST_DISABLE_PLUGIN_AUTOLOAD='1',PIPELINE_FORMULA_MATERIAL_SRC=str(material),PIPELINE_SELECTED_MATERIAL_SOURCE_ROOT=str(material),PIPELINE_FORMULA_LH2DT_SRC=str(lh2))
    for k in ('OMP_NUM_THREADS','MKL_NUM_THREADS','OPENBLAS_NUM_THREADS','NUMEXPR_NUM_THREADS'):env[k]='1'
    def execute(unit,p):
        name=unit.replace('.','-');xml=folder/(name+'.xml');log=folder/(name+'.log');start=time.monotonic()
        with log.open('w',encoding='utf-8') as stream:
            out=subprocess.run([sys.executable,'-m','pytest',*p['selectors'],'-q','--tb=short','-o','junit_family=xunit1','--junitxml='+str(xml)],cwd=ROOT,env=env,stdout=stream,stderr=subprocess.STDOUT)
        rows=[]
        if xml.is_file():
            for c in ET.parse(xml).iter('testcase'):
                status=next((s for s in ('failure','error','skipped') if c.find(s) is not None),'passed')
                r={'id':c.get('classname','')+'::'+c.get('name',''),'status':status}
                if status!='passed':r['diagnostic']=c.find(status).text
                rows.append(r)
        row={'model':unit,**p,'exit_code':out.returncode,'elapsed_s':time.monotonic()-start,'cases':rows,'junit':xml.name,'log':log.name}
        print(json.dumps({'model':unit,'exit_code':out.returncode,'cases':len(rows),'passed':sum(c['status']=='passed' for c in rows)}),flush=True)
        return row
    print(str(folder),flush=True);start=time.monotonic();runs=[];reused=[]
    if args.reuse_receipt:
        origin=args.reuse_receipt.resolve();prior=json.loads(origin.read_text(encoding='utf-8'))
        if prior['source_files_changed_during_run']:raise ValueError('cannot reuse a source-unstable campaign')
        if prior['python']!=sys.version or any(version(k)!=v for k,v in prior['packages'].items()):raise ValueError('reuse environment differs')
        old=prior['source_sha256']
        # Changing profile metadata does not invalidate numerical code; production,
        # examples, dependencies and each reused test file must still match exactly.
        required={k:v for k,v in old.items() if not k.startswith(str(ROOT/'tests')) and k!=str(Path(__file__).resolve()) and k!=str(catalog.resolve()) and k!=str(EXTRA_PROFILES.resolve())}
        if any(before.get(k)!=v for k,v in required.items()):raise ValueError('reuse production/example/dependency source differs')
        if any(k.startswith(str(ROOT/'src')) and k not in old for k in before):raise ValueError('new production source requires rerun')
        for row in prior['runs']:
            unit=row['model']
            if unit not in PROFILES or any(row[k]!=PROFILES[unit][k] for k in ('scope','criteria','selectors')):continue
            if row['exit_code'] or not row['cases'] or any(c['status']!='passed' for c in row['cases']):continue
            testpaths={str((ROOT/x.split('::')[0]).resolve()) for x in row['selectors']}
            if any(old.get(k)!=before.get(k) for k in testpaths):continue
            record=copy.deepcopy(row)
            if 'evidence_receipt' not in record:
                record['evidence_receipt']=origin.relative_to(ROOT).as_posix()
                record['evidence_receipt_sha256']=sha(origin)
                record['evidence_junit']=(origin.parent/record['junit']).relative_to(ROOT).as_posix()
                record['evidence_log']=(origin.parent/record['log']).relative_to(ROOT).as_posix()
            proof=ROOT/record['evidence_receipt']
            if sha(proof)!=record['evidence_receipt_sha256']:raise ValueError('reused evidence receipt changed')
            original=json.loads(proof.read_text(encoding='utf-8'))
            for key in ('evidence_junit','evidence_log'):
                artifact=ROOT/record[key]
                if sha(artifact)!=original['artifact_sha256'].get(artifact.name):raise ValueError('reused result artifact changed')
            runs.append(record);reused.append(unit)
    pending={u:p for u,p in PROFILES.items() if u not in reused}
    print(json.dumps({'reused_profiles':len(reused),'executing_profiles':len(pending),'workers':args.workers}),flush=True)
    with ThreadPoolExecutor(max_workers=args.workers) as pool:
        for f in as_completed([pool.submit(execute,u,p) for u,p in pending.items()]):runs.append(f.result())
    after=snapshot();changed=sorted(p for p in before.keys()|after.keys() if before.get(p)!=after.get(p))
    (folder/'source-after.json').write_text(json.dumps(after,ensure_ascii=False,indent=2),encoding='utf-8')
    passed={r['model'] for r in runs if r['exit_code']==0 and r['cases'] and all(c['status']=='passed' for c in r['cases'])} if not changed else set()
    cases=[c for r in runs for c in r['cases']]
    matrix=[{'id':u,'physical_profile_status':'passed_within_stated_scope' if u in passed else 'failed_or_incomplete' if u in PROFILES else 'not_assessed_in_this_campaign','scope':PROFILES.get(u,{}).get('scope')} for u in sorted(expected)]
    report={'schema':'pipeline_integrity.physical_campaign.v1','total_models':223,'reviewed_profiles':len(PROFILES),'passed_bounded_profiles':len(passed),'scope_coverage_percent':100*len(passed)/223,'unassessed_models':sorted(expected-set(PROFILES)),
      'cases':len(cases),**{s:sum(c['status']==s for c in cases) for s in ('passed','failure','error','skipped')},'runs':runs,'model_matrix':matrix,
      'source_files_changed_during_run':changed,'source_sha256':after,'elapsed_wall_s':time.monotonic()-start,'parallel_subprocesses':args.workers,'reused_profiles':reused,'executed_profiles_this_batch':sorted(pending),'reuse_receipt':str(args.reuse_receipt) if args.reuse_receipt else None,'python':sys.version,'platform':platform.platform(),'packages':{k:version(k) for k in ('pytest','numpy','scipy','pydantic','CoolProp','PyNiteFEA')},
      'independent_empirical_calibration_or_field_validation_claim':False,'whole_model_all_variants_qualified':False,'coverage_meaning':'Completed explicitly bounded physical profiles /223 fixed models. Algebraic agreement, a profile pass and empirical applicability are separate claims.',
      'retained_empirical_misses':'artifacts/regression-223/empirical_diagnostics.json','artifact_sha256':{p.name:sha(p) for p in folder.iterdir() if p.is_file()}}
    path=folder/'receipt.json';path.write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
    (folder.parent/'latest.json').write_text(json.dumps({'receipt':path.relative_to(ROOT).as_posix(),'sha256':sha(path)},indent=2),encoding='utf-8')
    print(json.dumps({k:report[k] for k in ('total_models','passed_bounded_profiles','scope_coverage_percent','cases','passed','failure','error','skipped','source_files_changed_during_run','elapsed_wall_s')}),flush=True)
    return int(len(passed)!=len(PROFILES) or bool(changed))
if __name__=='__main__':raise SystemExit(main())
